body:
I had a look and it did work for me with:

```xml
<dependency>
  <groupId>io.quarkus</groupId>
  <artifactId>quarkus-junit5-component</artifactId>
  <scope>test</scope>
</dependency>
<dependency>
  <groupId>io.quarkus</groupId>
  <artifactId>quarkus-junit5-config</artifactId>
  <scope>test</scope>
</dependency>
<dependency>
  <groupId>org.jboss.slf4j</groupId>
  <artifactId>slf4j-jboss-logmanager</artifactId>
</dependency>
```

And 

```java
package com.radcortez.quarkus.config;

import io.quarkus.test.component.QuarkusComponentTest;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import org.junit.jupiter.api.Test;
import org.slf4j.LoggerFactory;

@QuarkusComponentTest
public class LogTest {
    private static final org.slf4j.Logger logger = LoggerFactory.getLogger(LogTest.class);

    @Inject
    Foo foo;

    @Test
    void test() {
        logger.info("test");
    }

    @ApplicationScoped
    public static class Foo {

    }
}
```

Got the following output:

